import {courseLesson,edit} from './utility-authoring.js';
const L=(...args)=>courseLesson("match",...args);
export const matchUtilsLessons=[
L("ordinal","Parse an ordinal object reference",[4],"<p>Parsing separates the requested position from the remaining name. It does not search the world. An ordinal alone is not a complete reference. <code>parse_ordref()</code> is the shorter alias.</p>","text = \"second brush\";\nplayer:tell(\"ORDINAL parts: \", toliteral($match_utils:parse_ordinal_reference(text)));\nplayer:tell(\"ALIAS parts: \", toliteral($match_utils:parse_ordref(text)));\nplayer:tell(\"INCOMPLETE reference: \", toliteral($match_utils:parse_ordref(\"second\")));",edit("second brush","third brush","Request the third brush. The parsed position changes to 3."),{"server": {"names": ["parse_ordref"], "prerequisites": "ToastStunt with the original matching regex; the browser does not support its backreferences."}}),
L("possessive","Parse ownership language before matching",[5],"<p>Possessive parsing returns two strings. It turns <code>my</code> into <code>me</code>, ready for matching, but does not prove ownership or access. The remaining object name may be empty.</p>","player:tell(\"MY reference: \", toliteral($match_utils:parse_possessive_reference(\"my brush\")));\nplayer:tell(\"NAMED reference: \", toliteral($match_utils:parse_possessive_reference(\"Alex's saw\")));\nplayer:tell(\"NO possessive: \", toliteral($match_utils:parse_possessive_reference(\"brush\")));",edit("my brush","my hammer","Change the requested object. The owner token stays me while the object token becomes hammer.")),
L("candidates","Match within an explicit candidate list",[0, 1, 3],"<p>Provide a candidate list so matches have a clear scope. Prefix matches use object aliases. <code>match_list()</code> returns all matches; <code>match_nth()</code> selects one in list order. General <code>match()</code> also understands me, here, ordinals and literal object references; literal references can escape the candidate list, so matching is not authorization.</p>","candidates = {$string_utils, $list_utils};\nplayer:tell(\"ALL matches: \", toliteral($match_utils:match_list(\"List\", candidates)));\nplayer:tell(\"NTH matching object: \", toliteral($match_utils:match_nth(\"String\", candidates, 1)));\nplayer:tell(\"MATCH me: \", toliteral($match_utils:match(\"me\", candidates)));\nplayer:tell(\"MATCH literal: \", toliteral($match_utils:match(\"#55\", candidates)));",edit("match(\"#55\",","match(\"#27\",","Resolve Set Utils by its literal reference. The returned object changes even though it is not in the candidate list.")),
L("feedback","Explain an unsuccessful match",[6],"<p>A failed or ambiguous object reference is a sentinel object, not an exception. Pass it to <code>object_match_failed()</code> to print an appropriate message and return a failure flag. The caller should stop before using the invalid object.</p>","result = $failed_match;\nfailed = $match_utils:object_match_failed(result, \"brush\");\nplayer:tell(\"FAILURE flag: \", toliteral(failed));",edit("result = $failed_match;","result = $nothing;","Use the missing-name sentinel. The message asks for an object name instead of reporting that brush cannot be found.")),
L("command-dispatch","Separate command matching from programmatic calls",[2],"<p><code>match_verb()</code> uses the current parser variables and checks command argument specifications before dispatch. A programmatic verb with <code>this none this</code> is explicitly excluded by this helper, even though direct colon calls work.</p>","player:tell(\"COMMAND match programmatic verb: \", toliteral($match_utils:match_verb(\"range\", $list_utils, {3})));",edit("\"range\", $list_utils","\"make\", $list_utils","Try make instead. The programmatic argument specification still prevents command dispatch.")),
L("lookup-report","Build a parse-and-match report",[],"<p>Parse the input first and print its pieces before attempting a lookup. This makes it easier to distinguish malformed input from a valid reference that happens to find nothing.</p>","request = \"second brush\";\nparts = $match_utils:parse_ordref(request);\nplayer:tell(\"PARSED request: \", toliteral(parts));\nif (parts)\nplayer:tell(\"LOOKUP result: \", toliteral($match_utils:match_nth(parts[2], {}, parts[1])));\nendif",edit("second brush","third brush","Ask for the third brush. Parsing changes, but the empty candidate list still produces a failed match."),{"server": {"names": ["parse_ordref", "match_nth"], "prerequisites": "ToastStunt with the original matching regex; the browser does not support its backreferences."}}),
];
export const matchExclusions={"7": "Core initialization hook resets matching_room and calls its parent initializer. It is not an ordinary matching API and should not be run in a learner world."};
